/* --------------------------------------------------------------- outils --- */

function h($v) { return htmlspecialchars((string) $v, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8'); }

/** Décode le paquet embarqué et l'écrit dans un fichier temporaire. */
function paquet_fichier(): array
{
    $brut = base64_decode(preg_replace('/[^A-Za-z0-9+\/=]/', '', SEVE_PAQUET), true);
    if ($brut === false || strlen($brut) < 1000) { return [null, 'Le paquet embarqué est illisible.']; }
    $tmp = tempnam(sys_get_temp_dir(), 'seve') . '.zip';
    if (@file_put_contents($tmp, $brut) === false) { return [null, 'Impossible d’écrire le fichier temporaire.']; }
    return [$tmp, ''];
}

/** Liste [nom => contenu] du paquet, avec ZipArchive si présent. */
function paquet_entrees_ziparchive(string $fichier): array
{
    $z = new ZipArchive();
    if ($z->open($fichier) !== true) { return []; }
    $out = [];
    for ($i = 0; $i < $z->numFiles; $i++) {
        $nom = (string) $z->getNameIndex($i);
        if ($nom === '' || substr($nom, -1) === '/') { continue; }
        $out[$nom] = (string) $z->getFromIndex($i);
    }
    $z->close();
    return $out;
}

/**
 * Relecture du ZIP sans l'extension zip : on lit le répertoire central du
 * fichier (fin d'archive), puis chaque entrée. Utile sur un hébergement où
 * l'extension « zip » de PHP n'est pas activée.
 */
function paquet_entrees_manuel(string $fichier): array
{
    $d = (string) @file_get_contents($fichier);
    $eocd = strrpos($d, "PK\x05\x06");
    if ($eocd === false) { return []; }
    $nb = unpack('v', substr($d, $eocd + 10, 2))[1];
    $pos = unpack('V', substr($d, $eocd + 16, 4))[1];
    $out = [];
    for ($i = 0; $i < $nb; $i++) {
        if (substr($d, $pos, 4) !== "PK\x01\x02") { break; }
        $methode = unpack('v', substr($d, $pos + 10, 2))[1];
        $tailleC = unpack('V', substr($d, $pos + 20, 4))[1];
        $lenNom  = unpack('v', substr($d, $pos + 28, 2))[1];
        $extra   = unpack('v', substr($d, $pos + 30, 2))[1];
        $comment = unpack('v', substr($d, $pos + 32, 2))[1];
        $local   = unpack('V', substr($d, $pos + 42, 4))[1];
        $nom = substr($d, $pos + 46, $lenNom);
        $lenNomL = unpack('v', substr($d, $local + 26, 2))[1];
        $extraL  = unpack('v', substr($d, $local + 28, 2))[1];
        $debut = $local + 30 + $lenNomL + $extraL;
        $brut = substr($d, $debut, $tailleC);
        $contenu = ($methode === 8) ? @gzinflate($brut) : $brut;
        if ($contenu !== false && $nom !== '' && substr($nom, -1) !== '/') { $out[$nom] = $contenu; }
        $pos += 46 + $lenNom + $extra + $comment;
    }
    return $out;
}

/** Écrit les entrées ; renvoie [écrits, ignorés, erreurs]. */
function installer(array $entrees): array
{
    global $CIBLE;
    $ecrits = 0; $ignores = 0; $erreurs = [];
    foreach ($entrees as $nom => $contenu) {
        $rel = ltrim(str_replace('\\', '/', $nom), '/');
        if (strpos($rel, '..') !== false) { continue; }
        /* Les relevés des créatrices ne sont JAMAIS écrasés. */
        if (preg_match('#^seve/data/of-[0-9a-f]+\.(json|json\.lock)$#', $rel) && file_exists(dirname($CIBLE) . '/' . $rel)) {
            $ignores++;
            continue;
        }
        $dest = dirname($CIBLE) . '/' . $rel;
        /* Les réglages propres au site (boîte e-mail, clé du mode refuge)
           survivent à une mise à jour. Une installation neuve les crée. */
        if (in_array($rel, ['seve/config.php', 'seve/config-local-seve.php'], true) && is_file($dest)) {
            $ignores++;
            continue;
        }
        $dossier = dirname($dest);
        if (!is_dir($dossier) && !@mkdir($dossier, 0755, true) && !is_dir($dossier)) {
            $erreurs[] = 'dossier impossible : ' . $rel;
            continue;
        }
        if (@file_put_contents($dest, $contenu) === false) { $erreurs[] = 'écriture impossible : ' . $rel; }
        else { $ecrits++; }
    }
    return [$ecrits, $ignores, $erreurs];
}

