$etape = 'accueil';
$ecrits = 0; $ignores = 0; $erreurs = []; $methode = '';
$dejaLa = file_exists($CIBLE . '/index.php');

if (($_SERVER['REQUEST_METHOD'] ?? 'GET') === 'POST' && isset($_POST['action'])) {
    $cle = (string)($_POST['cle_installation'] ?? '');
    if (!hash_equals(SEVE_INSTALL_HASH, hash('sha256', $cle)) || $cle === '') {
        $etape = 'echec'; $erreurs[] = 'Clé d’installation incorrecte.';
    } elseif ($_POST['action'] === 'supprimer') {
        if (!@unlink(__FILE__)) { $etape = 'echec'; $erreurs[] = 'Supprimez manuellement l’installateur.'; }
        else { $etape = 'supprime'; }
    } elseif (!in_array($_POST['action'], ['installer'], true)) {
        $etape = 'echec'; $erreurs[] = 'Action inconnue.';
    } elseif (($_SERVER['HTTPS'] ?? '') !== 'on' && ($_SERVER['HTTP_X_FORWARDED_PROTO'] ?? '') !== 'https'
        && PHP_SAPI !== 'cli-server') {
        $etape = 'echec'; $erreurs[] = 'Utilisez HTTPS pour définir le mot de passe administrateur.';
    } elseif (PHP_VERSION_ID < 80100 || !extension_loaded('pdo_sqlite') || !extension_loaded('gd')) {
        $etape = 'echec'; $erreurs[] = 'PHP 8.1+ et extensions pdo_sqlite et gd requis avant l’installation.';
    } elseif (strlen((string)($_POST['admin_password'] ?? '')) < 14 ||
        (string)($_POST['admin_password'] ?? '') !== (string)($_POST['admin_confirmation'] ?? '')) {
        $etape = 'echec'; $erreurs[] = 'Mot de passe admin : 14 caractères minimum et confirmation identique.';
    } else {
        [$tmp, $souci] = paquet_fichier();
        if ($tmp === null) {
            $etape = 'echec'; $erreurs[] = $souci;
        } elseif (!is_writable(is_dir($CIBLE) ? $CIBLE : $RACINE)) {
            /* On le dit tout de suite : sinon on écrit 75 erreurs identiques. */
            $etape = 'echec';
            $erreurs[] = is_dir($CIBLE)
                ? 'Le dossier « seve » existe mais n’autorise pas l’écriture :'
                  . ' dans le gestionnaire de fichiers, clic droit sur « seve » → Permissions → 755, puis relancez.'
                : 'Le dossier n’a pas pu être créé à côté de cet installateur :'
                  . ' dans le gestionnaire de fichiers, clic droit sur le dossier qui contient cet installateur → Permissions → 755, puis relancez.';
        } else {
            $manuel = isset($_POST['mode']) && $_POST['mode'] === 'manuel';
            $entrees = (!$manuel && class_exists('ZipArchive')) ? paquet_entrees_ziparchive($tmp) : [];
            $methode = (!$manuel && class_exists('ZipArchive')) ? 'ZipArchive' : 'lecture directe';
            if (!$entrees) { $entrees = paquet_entrees_manuel($tmp); $methode = 'lecture directe'; }
            @unlink($tmp);
            if (!$entrees) {
                $etape = 'echec'; $erreurs[] = 'Le paquet n’a pas pu être lu.';
            } else {
                [$ecrits, $ignores, $erreurs] = installer($entrees);
                if (!$erreurs) {
                    /* L’ouverture est la DERNIÈRE écriture : admin et mode sont
                       installés avant de rendre l’API publique. */
                    $local = $CIBLE . '/config-local-seve.php';
                    $ancien = is_file($local) ? (array)require $local : [];
                    $ancien['admin_identifiant'] = (string)($ancien['admin_identifiant'] ?? 'admin');
                    $ancien['admin_hash'] = password_hash((string)$_POST['admin_password'], PASSWORD_DEFAULT);
                    $mode = $CIBLE . '/data/mode.json';
                    if (@file_put_contents($local, "<?php
return " . var_export($ancien, true) . ";
", LOCK_EX) === false) {
                        $erreurs[] = 'Impossible d’enregistrer l’administration Sève.';
                    } else {
                        @chmod($local, 0600);
                        if (@file_put_contents($mode, '{"refuge":true}', LOCK_EX) === false) {
                            $erreurs[] = 'Impossible d’activer le mode refuge global.';
                        } else {
                            $cfgPath = $CIBLE . '/config.php';
                            $cfg = (string)@file_get_contents($cfgPath);
                            $nouveau = preg_replace("/('ouverture_publique'\s*=>\s*)(true|false)/", '${1}true', $cfg, 1, $nb);
                            if ($nb !== 1) $erreurs[] = 'Réglage d’ouverture introuvable dans config.php.';
                            else {
                                $nouveau = preg_replace("/('noindex'\s*=>\s*)(true|false)/", '${1}false', $nouveau, 1);
                                if (@file_put_contents($cfgPath, $nouveau, LOCK_EX) === false) $erreurs[] = 'Impossible d’activer le site dans config.php.';
                            }
                        }
                    }
                }
                $etape = $erreurs ? 'partiel' : 'fini';
            }
        }
    }
}
